**Function**: poly_function

```c
// C program for the function called poly_function
// Contains target function implementation and dependency signatures

#include <complex.h>
#include <limits.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Target function implementation
long double complex poly_function(long double *coeffs, unsigned int degree,
                                  long double complex x)
{
    long double complex out = 0.;
    unsigned int n;

    if (coeffs == NULL || degree == 0) {
        return 0.;
    }

    for (n = 0; n < degree; n++) out += coeffs[n] * cpow(x, degree - n - 1);

    return out;
}

```

